mapper.select:
select c.cust_id, c.cust_cd, c.cust_nm, s.trade_status, s.currency_cd, s.pay_terms_cd
  from mst_cust c join srm_supplier s on s.cust_id = c.cust_id
 where c.cust_cd = #{custCd}

mapper.sql:
 where p.po_date between #{c.from} and #{c.to}
and p.status = #{c.status}
and c.cust_cd = #{c.custCd}

   and (p.po_no ilike #{c.keywordLike} escape '\' or c.cust_nm ilike #{c.keywordLike} escape '\'
        or exists (select 1 from mst_ext_id_map m where m.entity_type = 'PO' and m.internal_id = p.po_id and m.use_yn = 'Y'
                    and m.external_id ilike #{c.keywordLike} escape '\')
        or exists (select 1 from srm_po_line l join mst_item i on i.item_id = l.item_id
                    where l.po_id = p.po_id and (i.item_cd ilike #{c.keywordLike} escape '\' or l.item_nm ilike #{c.keywordLike} escape '\')))

mapper.update:
update srm_po
   set status = #{to},
       apr_request_id = coalesce(#{aprRequestId}::bigint, apr_request_id),
       cancel_reason = case when #{to} = 'CANCELLED' then #{cancelReason} else cancel_reason end,
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where po_id = #{id} and status = #{from} and row_ver = #{rowVer}

update srm_po
   set status = 'ISSUED', issued_at = now(), issued_by = #{by}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where po_id = #{id} and status = 'APPROVED' and row_ver = #{rowVer}

update srm_po
   set status = 'DRAFT', rev = case when status in ('ISSUED', 'ACKED') then rev + 1 else rev end,
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where po_id = #{id} and status = #{from} and row_ver = #{rowVer}

mapper.insert:
insert into srm_po_rev (comp_cd, po_id, rev, issued_by, snapshot, created_by)
select p.comp_cd, p.po_id, p.rev, #{by},
       ,
       #{by}
  from srm_po p join mst_cust c on c.cust_id = p.cust_id left join mst_equip_hier w on w.node_id = p.wh_id
 where p.po_id = #{id}

mapper.select:
select ()::text
  from srm_po p join mst_cust c on c.cust_id = p.cust_id left join mst_equip_hier w on w.node_id = p.wh_id
 where p.po_id = #{id}

mapper.update:
update srm_po
   set status = #{to}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where po_id = #{id} and status = 'IN_APPROVAL'

